2	import { renderHook, act } from '@testing-library/react';
3	import { useFilterDrawerState, buildAppliedRefine } from './useFilterDrawerState';
4	
5	describe('useFilterDrawerState', () => {
6	  test('resyncs pending state from currently-applied filters when the drawer opens', () => {
7	    const { result, rerender } = renderHook(
8	      ({ isOpen }) =>
9	        useFilterDrawerState({
10	          isOpen,
11	          categoryId: 'clothing',
12	          selectedRefinements: { c_size: 'S|M', cgid: 'clothing' },
13	        }),
14	      { initialProps: { isOpen: false } },
15	    );
16	
17	    expect(result.current.pendingRefine).toEqual({});
18	
19	    rerender({ isOpen: true });
20	
21	    // cgid is excluded — category is tracked separately via pendingCategoryId, not as a
22	    // refinement value, matching product-list/index.tsx's own toggleFilter-vs-navigation split.
23	    expect(result.current.pendingRefine).toEqual({ c_size: ['S', 'M'] });
24	    expect(result.current.pendingCategoryId).toBe('clothing');
25	  });
26	
27	  test('setValues replaces the full value set for an attribute (checkbox group onChange)', () => {
28	    const { result } = renderHook(() =>
29	      useFilterDrawerState({ isOpen: true, categoryId: 'clothing', selectedRefinements: {} }),
30	    );
31	
32	    act(() => result.current.setValues('c_refinementColor', ['Black', 'White']));
33	    expect(result.current.pendingRefine).toEqual({ c_refinementColor: ['Black', 'White'] });
34	
35	    act(() => result.current.setValues('c_refinementColor', []));
36	    expect(result.current.pendingRefine).toEqual({});
37	  });
38	
39	  test('removeValue drops a single value without touching other attributes', () => {
40	    const { result } = renderHook(() =>
41	      useFilterDrawerState({ isOpen: true, categoryId: 'clothing', selectedRefinements: {} }),
42	    );
43	
44	    act(() => {
45	      result.current.setValues('c_refinementColor', ['Black', 'White']);
46	      result.current.setValues('c_size', ['S']);
47	    });
48	
49	    act(() => result.current.removeValue('c_refinementColor', 'Black'));
50	
51	    expect(result.current.pendingRefine).toEqual({ c_refinementColor: ['White'], c_size: ['S'] });
52	  });
53	
54	  test('removeValue clears the attribute key entirely once its last value is removed', () => {
55	    const { result } = renderHook(() =>
56	      useFilterDrawerState({ isOpen: true, categoryId: 'clothing', selectedRefinements: {} }),
57	    );
58	
59	    act(() => result.current.setValues('c_size', ['S']));
60	    act(() => result.current.removeValue('c_size', 'S'));
61	
62	    expect(result.current.pendingRefine).toEqual({});
63	  });
64	
65	  test('clearAll resets every pending refinement but leaves pendingCategoryId untouched', () => {
66	    const { result } = renderHook(() =>
67	      useFilterDrawerState({ isOpen: true, categoryId: 'clothing', selectedRefinements: {} }),
68	    );
69	
70	    act(() => {
71	      result.current.setValues('c_size', ['S']);
72	      result.current.setPendingCategoryId('dresses');
73	    });
74	
75	    act(() => result.current.clearAll());
76	
77	    expect(result.current.pendingRefine).toEqual({});
78	    expect(result.current.pendingCategoryId).toBe('dresses');
79	  });
80	
81	  test('resyncPendingRefine restores pendingRefine from a given selectedRefinements snapshot on demand', () => {
82	    const { result } = renderHook(() =>
83	      useFilterDrawerState({ isOpen: true, categoryId: 'clothing', selectedRefinements: {} }),
84	    );
85	
86	    // Simulates a category change (clearAll via handleCategoryChange) followed by the
87	    // shopper reverting it via the category chip's onRemove — pendingRefine must come back
88	    // from the real applied refine, not stay empty.
89	    act(() => result.current.clearAll());
90	    expect(result.current.pendingRefine).toEqual({});
91	
92	    act(() => result.current.resyncPendingRefine({ c_refinementColor: 'Black|White', cgid: 'clothing' }));
93	
94	    expect(result.current.pendingRefine).toEqual({ c_refinementColor: ['Black', 'White'] });
95	  });
96	
97	  test('buffers selections across several facet groups simultaneously without them interfering', () => {
98	    const { result } = renderHook(() =>
99	      useFilterDrawerState({ isOpen: true, categoryId: 'tops', selectedRefinements: {} }),
100	    );
101	
102	    act(() => {
103	      result.current.setValues('c_refinementColor', ['Blue', 'Green']);
104	      result.current.setValues('c_size', ['0', '1']);
105	      result.current.setValues('c_material', ['Cotton']);
106	      result.current.setPendingCategoryId('tops');
107	    });
108	
109	    expect(result.current.pendingRefine).toEqual({
110	      c_refinementColor: ['Blue', 'Green'],
111	      c_size: ['0', '1'],
112	      c_material: ['Cotton'],
113	    });
114	
115	    // Removing one Colour value doesn't disturb Size or Material's own buffered selections.
116	    act(() => result.current.removeValue('c_refinementColor', 'Blue'));
117	    expect(result.current.pendingRefine).toEqual({
118	      c_refinementColor: ['Green'],
119	      c_size: ['0', '1'],
120	      c_material: ['Cotton'],
121	    });
122	  });
123	});
124	
125	describe('buildAppliedRefine', () => {
126	  test('overwrites every managed attribute from pendingRefine and leaves unmanaged ones untouched', () => {
127	    // Real SFCC-847 shape: cgid=tops already applied via a previous category navigation,
128	    // c_refinementColor=Blue already applied from a previous APPLY, and ilids (store
129	    // inventory — not one of this drawer's facet groups at all) already applied too.
130	    const currentRefine = { cgid: 'tops', c_refinementColor: 'Blue', ilids: 'store123' };
131	    const managedAttributeIds = ['c_refinementColor', 'c_size', 'c_material'];
132	    const pendingRefine = {
133	      c_refinementColor: ['Blue', 'Green'],
134	      c_size: ['0', '1'],
135	      c_material: ['Cotton'],
136	    };
137	
138	    const result = buildAppliedRefine(currentRefine, managedAttributeIds, pendingRefine);
139	
140	    expect(result).toEqual({
141	      cgid: 'tops',
142	      ilids: 'store123',
143	      c_refinementColor: ['Blue', 'Green'],
144	      c_size: ['0', '1'],
145	      c_material: ['Cotton'],
146	    });
147	  });
148	
149	  test('deletes a managed attribute the shopper unticked back to empty', () => {
150	    // c_size was applied before (from a prior APPLY) but the shopper unticked every Size
151	    // value in this drawer session — pendingRefine has no c_size key at all, so the real
152	    // refine must drop it, not carry the stale value forward.
153	    const currentRefine = { c_refinementColor: 'Blue', c_size: '0|1' };
154	    const managedAttributeIds = ['c_refinementColor', 'c_size', 'c_material'];
155	    const pendingRefine = { c_refinementColor: ['Blue'] };
156	
157	    const result = buildAppliedRefine(currentRefine, managedAttributeIds, pendingRefine);
158	
159	    expect(result).toEqual({ c_refinementColor: ['Blue'] });
160	  });
161	
162	  test('never mutates the currentRefine object it was given', () => {
163	    const currentRefine = { c_size: '0' };
164	    buildAppliedRefine(currentRefine, ['c_size'], { c_size: ['1', '2'] });
165	
166	    expect(currentRefine).toEqual({ c_size: '0' });
167	  });
168	});
