361	          window.localStorage.setItem(CATEGORY_OPTIONS_STORAGE_KEY, JSON.stringify(category.categories));
362	        } catch {
363	          // Ignore — see comment above.
364	        }
365	      }
366	    }
367	  }, [category]);
368	
369	  /**************** Error Handling ****************/
370	  const errorStatus = (error as { response?: { status?: number } } | null)?.response?.status;
371	  switch (errorStatus) {
372	    case undefined:
373	      // No Error.
374	      break;
375	    case 404:
376	      throw new HTTPNotFound('Category Not Found.');
377	    default:
378	      throw new HTTPError(errorStatus, `HTTP Error ${errorStatus} occurred.`);
379	  }
380	
381	  /**************** Response Handling ****************/
382	  if (res) {
383	    res.set('Cache-Control', `s-maxage=${MAX_CACHE_AGE}, stale-while-revalidate=${STALE_WHILE_REVALIDATE}`);
384	  }
