406	  const parentCategoryId = (category as { parentCategoryId?: string } | undefined)?.parentCategoryId;
407	
408	  // SFCC-847 — every selection in the drawer (category + every refinement facet) is
409	  // buffered locally via useFilterDrawerState rather than applied straight to the URL on
410	  // each click. Matches how the Storybook stories for this drawer already behaved (no
411	  // navigation on selection) and makes APPLY the single moment that actually commits.
412	  // Resyncs from the page's real applied filters every time the drawer opens (see the
413	  // hook's own docblock). Pass searchParams.refine (the URL-derived ground truth) as the
