417	  const {
418	    pendingCategoryId,
419	    setPendingCategoryId,
420	    pendingRefine,
421	    setValues,
422	    removeValue,
423	    clearAll,
424	    resyncPendingRefine,
425	  } = useFilterDrawerState({
426	    isOpen: filterDrawer.isOpen,
427	    categoryId: params.categoryId,
