489	      const current = pendingRefine[attributeId]?.[0];
490	      setValues(attributeId, current === stringValue ? [] : [stringValue]);
491	      return;
492	    }
493	    if (selected) {
494	      removeValue(attributeId, stringValue);
495	    } else {
496	      setValues(attributeId, [...(pendingRefine[attributeId] ?? []), stringValue]);
