507	  const { data: pendingCategoryResult } = useProductSearch(
508	    {
509	      parameters: {
510	        limit: 1,
511	        refine: [`cgid=${pendingCategoryId ?? ''}`] as unknown as string,
512	      },
513	    },
514	    {
515	      // Only fires when the drawer is open with a different category pending.
516	      enabled: pendingCategoryChanged,
