import { describe, test, expect } from 'vitest';
import { renderHook } from '@testing-library/react';
import { useFilterDrawerState } from './useFilterDrawerState';

// THROWAWAY — verifying a suspected stale-closure bug for PR #117 review.
// Not part of the PR; deleted immediately after running.
describe('SCRATCH: stale prop while isOpen stays true', () => {
  test('pendingCategoryId does NOT resync when categoryId prop changes but isOpen stays true', () => {
    const { result, rerender } = renderHook(
      ({ categoryId, selectedRefinements }) =>
        useFilterDrawerState({ isOpen: true, categoryId, selectedRefinements }),
      { initialProps: { categoryId: 'dresses', selectedRefinements: {} as Record<string, string> } },
    );

    // Drawer opens on 'dresses' (mount always runs the layout effect once).
    expect(result.current.pendingCategoryId).toBe('dresses');

    // Simulates: shopper has the drawer open (isOpen never changes), then the browser
    // back/forward button (or any other same-tab navigation not gated by the drawer's own
    // onOpen/onClose) changes params.categoryId to a different category. isOpen stays true.
    rerender({ categoryId: 'clothing', selectedRefinements: {} as Record<string, string> });

    // What SHOULD happen: pendingCategoryId re-seeds to the new real category ('clothing'),
    // since the drawer is still open and showing (or about to show) that category's own facets.
    // What ACTUALLY happens: the useLayoutEffect's dependency array is [isOpen] only, and isOpen
    // never changed, so the effect never re-fires — pendingCategoryId is stuck at the OLD value.
    console.log('pendingCategoryId after categoryId prop change (isOpen unchanged):', result.current.pendingCategoryId);
    expect(result.current.pendingCategoryId).toBe('clothing'); // <-- expected to FAIL, proving the bug
  });
});

