import { describe, test, expect } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { useFilterDrawerState } from './useFilterDrawerState';

// THROWAWAY — verifying a suspected race in index.tsx's handleBufferedToggle composition
// for PR #117 review. Reproduces its exact "add" branch:
//   setValues(attributeId, [...(pendingRefine[attributeId] ?? []), stringValue])
// which reads `pendingRefine` from the render-time closure, not from setPendingRefine's own
// `prev` updater. Not part of the PR; deleted immediately after running.
describe('SCRATCH: rapid double-toggle race in the setValues(...[...pendingRefine[attr], v]) pattern', () => {
  test('two rapid adds to the SAME attribute (different values) both reading stale pendingRefine', () => {
    const { result } = renderHook(() =>
      useFilterDrawerState({ isOpen: true, categoryId: 'clothing', selectedRefinements: {} }),
    );

    expect(result.current.pendingRefine).toEqual({});

    // Simulates index.tsx's handleBufferedToggle being called twice in rapid succession
    // (e.g. two fast clicks on "Black" then "White" checkboxes) before either state update
    // has been committed and re-rendered — both reads of `pendingRefine` below capture the
    // SAME stale snapshot, exactly like two event handlers firing off the same render.
    const pendingRefineSnapshotBeforeEither = result.current.pendingRefine;

    act(() => {
      // Click 1: toggle "Black" on for c_refinementColor.
      result.current.setValues('c_refinementColor', [
        ...(pendingRefineSnapshotBeforeEither['c_refinementColor'] ?? []),
        'Black',
      ]);
      // Click 2: toggle "White" on for c_refinementColor — reads the SAME stale snapshot,
      // not the result of click 1, because handleBufferedToggle's `pendingRefine` reference
      // is the outer component-render closure, not a functional updater's `prev`.
      result.current.setValues('c_refinementColor', [
        ...(pendingRefineSnapshotBeforeEither['c_refinementColor'] ?? []),
        'White',
      ]);
    });

    console.log('pendingRefine after both rapid adds:', JSON.stringify(result.current.pendingRefine));
    // What SHOULD happen: both Black AND White end up selected — the shopper clicked two
    // different swatches, both should stick.
    expect(result.current.pendingRefine).toEqual({ c_refinementColor: ['Black', 'White'] }); // <-- expected to FAIL
  });
});

