// Pure-arithmetic simulation of index.tsx's chip-window offset state machine, copied verbatim
// from the PR source (safeChipOffset formula at line 898, SelectedChipRow's onRemove decrement
// at line 216-219). No React needed — this only exercises the arithmetic across a sequence of
// renders to check whether the raw `chipOffset` state can resurface incorrectly after a
// remove-then-add round trip. Throwaway — for PR #117 review verification only.

let chipOffset = 0; // raw persisted state (what setChipOffset actually stores)
const chipsPerPage = 3; // xl/desktop breakpoint per useBreakpointValue({ base: 1, lg: 2, xl: 3 })

function render(pageChipsLength) {
  const safeChipOffset = Math.min(chipOffset, Math.max(0, pageChipsLength - chipsPerPage));
  const canChipRight = safeChipOffset + chipsPerPage < pageChipsLength;
  return { safeChipOffset, canChipRight };
}

// Step 1: 4 applied chips, initial render.
let pageChipsLength = 4;
let r = render(pageChipsLength);
console.log('Step 1 (4 chips, initial):', r, 'raw chipOffset =', chipOffset);

// Step 2: user clicks "Next chips" once (chevron-right), per SelectedChipRow's
// onClick={() => onOffsetChange(offset + 1)} where offset === safeChipOffset.
chipOffset = r.safeChipOffset + 1;
r = render(pageChipsLength);
console.log('Step 2 (after Next click):', r, 'raw chipOffset =', chipOffset);

// Step 3: user removes one of the 3 visible chips. Replicate SelectedChipRow's exact onRemove
// decrement condition, evaluated BEFORE the chip list has shrunk (chips.length is still 4,
// offset is the current safeChipOffset from step 2):
const offsetAtRemovalTime = r.safeChipOffset; // 1
const chipsLengthAtRemovalTime = pageChipsLength; // 4 (pre-removal)
if (offsetAtRemovalTime > 0 && offsetAtRemovalTime >= chipsLengthAtRemovalTime - 1) {
  chipOffset = offsetAtRemovalTime - 1;
  console.log('  -> decrement fired, chipOffset set to', chipOffset);
} else {
  console.log(
    '  -> decrement condition FALSE (offset',
    offsetAtRemovalTime,
    '>= chips.length-1',
    chipsLengthAtRemovalTime - 1,
    'is',
    offsetAtRemovalTime >= chipsLengthAtRemovalTime - 1,
    ') — chipOffset stays',
    chipOffset,
  );
}
pageChipsLength = 3; // the chip is now actually gone
r = render(pageChipsLength);
console.log('Step 3 (after removal, list now 3 long):', r, 'raw chipOffset =', chipOffset);
console.log('  Display looks correct this render (safeChipOffset clamped to', r.safeChipOffset, ') — masking the stale raw chipOffset.');

// Step 4: user adds a new filter via drawer Apply, growing the list back to 4 — WITHOUT ever
// touching the prev/next arrows again.
pageChipsLength = 4;
r = render(pageChipsLength);
console.log('Step 4 (list grows back to 4 chips, no arrow click in between):', r, 'raw chipOffset =', chipOffset);

if (r.safeChipOffset !== 0) {
  console.log(
    '\nBUG CONFIRMED: window silently jumped to offset',
    r.safeChipOffset,
    'hiding chip[0] even though the user never clicked "Next chips" again after the removal.',
  );
} else {
  console.log('\nNo bug: offset correctly stayed at 0.');
}

