import { describe, test, expect } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { useFilterDrawerState } from './useFilterDrawerState';

// THROWAWAY — verifying index.tsx's handleCategoryChange revert-path claim ("Reverting back
// to the current category restores whatever the URL already has applied (resync effect
// handles that on the next open)") for PR #117 review. Reproduces handleCategoryChange's exact
// composition (setPendingCategoryId + conditional clearAll) against the real hook, drawer
// staying open throughout (no isOpen transition, so the useLayoutEffect never re-fires).
// Not part of the PR; deleted immediately after running.
describe('SCRATCH: category radio A -> B -> A revert while drawer stays open', () => {
  test('pendingRefine should be restored to what is actually applied for A once reverted, not stuck empty', () => {
    const APPLIED_CATEGORY = 'dresses';
    const APPLIED_REFINEMENTS = { c_refinementColor: 'Black', cgid: APPLIED_CATEGORY };

    const { result } = renderHook(() =>
      useFilterDrawerState({
        isOpen: true,
        categoryId: APPLIED_CATEGORY,
        selectedRefinements: APPLIED_REFINEMENTS,
      }),
    );

    // Drawer opens on 'dresses' with colour=Black already applied — matches the layout
    // effect's resync on mount/open.
    expect(result.current.pendingCategoryId).toBe(APPLIED_CATEGORY);
    expect(result.current.pendingRefine).toEqual({ c_refinementColor: ['Black'] });

    // handleCategoryChange('tops') — tentative switch away from the applied category:
    // setPendingCategoryId(newCategoryId); if (newCategoryId !== params.categoryId) clearAll();
    act(() => {
      result.current.setPendingCategoryId('tops');
      result.current.clearAll(); // 'tops' !== 'dresses' (params.categoryId) => true branch
    });
    expect(result.current.pendingRefine).toEqual({});

    // handleCategoryChange('dresses') — shopper reverts back to the ORIGINAL applied category
    // via the radio. newCategoryId ('dresses') === params.categoryId ('dresses'), so per
    // index.tsx's own condition, clearAll() is NOT called this time — and nothing else in
    // handleCategoryChange calls resyncPendingRefine either.
    act(() => {
      result.current.setPendingCategoryId('dresses');
      // (newCategoryId === params.categoryId branch: clearAll() intentionally skipped, matching
      // index.tsx's `if (newCategoryId !== params.categoryId) clearAll();`)
    });

    console.log('pendingRefine after A -> B -> A revert (drawer never closed):', JSON.stringify(result.current.pendingRefine));
    // index.tsx's own comment claims this is fine because "the resync effect handles that on
    // the next open" — but isOpen never changed (drawer stayed open throughout), so the
    // useLayoutEffect (deps=[isOpen]) never re-fires. Expected per that comment: pendingRefine
    // restored to {c_refinementColor: ['Black']}, matching what's actually applied for 'dresses'.
    expect(result.current.pendingRefine).toEqual({ c_refinementColor: ['Black'] }); // <-- expected to FAIL
  });
});

